BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-009','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題考身心障礙者權利公約第20條（個人行動能力）：締約國應促進身心障礙者依其選擇之方式、時間，以可負擔之費用享有個人行動能力；促進其獲得優質之行動輔具、用品、輔助技術及各種形式之現場協助及中介；提供身心障礙者及與其共事之專業人員行動技能培訓；鼓勵行動輔具、用品與輔助技術之生產者斟酌身心障礙者行動能力之所有面向。選項(A)要求依社區服務方式、所訂時間和付費模式參加，與第20條依其選擇之方式、時間之規定不符，非屬公約規定。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-107-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考身心障礙者權利公約第14條（人身自由及安全）：締約國應確保身心障礙者在與其他人平等基礎上享有人身自由及安全之權利，不被非法或任意剝奪自由。臨床工作者受家屬要求拒絕精神病人自行辦理結案，違反人身自由及安全之規定（選項B）；尊重隱私（第22條）、個人行動能力（第20條）及教育（第24條）與題旨不符。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-110-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考身心障礙者權利公約第1條宗旨：促進、保障與確保所有身心障礙者充分及平等享有所有人權及基本自由，並促進對身心障礙者固有尊嚴之尊重，公約主要強調人權之保障（選項C）。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-111-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考身心障礙者權利公約之合理調整精神。第2條定義合理之對待（合理調整），指根據具體需要進行必要及適當之修改與調整，以確保身心障礙者在與其他人平等基礎上享有或行使所有人權及基本自由；第5條要求締約國採取一切適當步驟確保提供合理之對待，第24條並要求於教育中提供合理之對待。考試空間與時間與修課同學一致係齊頭式對待，未提供合理之對待，無法彰顯公約精神（選項D）；手語翻譯、導盲犬陪同及輪椅推送均屬合理之對待。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-113-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-07-27。本題考身心障礙者權利公約原則之實踐。第9條要求締約國採取適當措施，確保身心障礙者在與其他人平等基礎上無障礙使用物理環境、設施及服務，補助藥局增改建無障礙設施（①）符合公約；第4條第1項第6款要求締約國進行或促進研究發展通用設計之貨物、服務、設備及設施，為身心障礙者研製特殊口罩（④）符合公約；第11條要求於危險情況及人道緊急情況中採取一切必要措施確保身心障礙者獲得保護及安全，②以醫護人員不戴口罩因應，未兼顧防疫安全；③認為提供特殊需求者個別配送會破壞公平機制，與合理之對待精神不符。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>5 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>5 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'e2c086f9e5d1a828a313a071b2edc6a6' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_5, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_5 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
